{
  "selections": [
    {
      "trait_id": "/core_belief/core_belief_statement",
      "background_ids": ["/childhood_data", "/situations/1"],
      "relevance": "상담사가 아내 앞에서 말할 때 '뭐가 없어서' 말하지 못하는지 물음. 내담자가 식탁에서 아내의 질문에 보일러 점검으로 화제를 돌린 것은 '감정을 드러내는 것은 위험하고 수치스러운 일이므로 늘 눌러 숨겨야 한다'는 핵심 신념이 작동한 결과이며, 그 신념이 형성된 성장 배경(아버지에게 감정 표현 시 수치·징벌을 경험)과 직접 연결됨."
    },
    {
      "trait_id": "/intermediate_beliefs/assumption_negative",
      "background_ids": ["/situations/1"],
      "relevance": "상담사가 '여기서 말하는 거랑 그 앞에서 말하는 거랑 다르다'는 차이를 물음. 아내 앞에서 감정을 꺼내면 '둑이 터지듯 통제를 잃을 것'이라는 부정적 가정이, 식탁에서 아내의 질문에 아무 말도 하지 못하고 수저를 놓고 들어가는 뒷모습만 보게 한 원동력으로 작용함."
    },
    {
      "trait_id": "/coping_strategies/0",
      "background_ids": ["/situations/1"],
      "relevance": "내담자가 '아내 앞에서 말하기'를 회피한 구체적 방식이 '슬픔이 올라오는 순간 화제를 실무적 것으로 돌림'이라는 대처 전략과 정확히 일치. 보일러 점검 예약으로 화제를 돌린 장면이 이 전략의 대표적 사례임."
    },
    {
      "trait_id": "/coping_strategies/3",
      "background_ids": ["/situations/1"],
      "relevance": "아내의 '괜찮은 거야? 속에 있는 말 좀 해봐'는 '요즘 기분이 어떠냐'는 질문과 동일한 구조이며, 내담자가 이 질문에 보일러 점검으로 답한 것은 자신의 상태를 묻는 대화 자체를 어색해하고 서둘러 끝내는 패턴에 해당함."
    },
    {
      "trait_id": "/intermediate_beliefs/rule",
      "background_ids": ["/childhood_data"],
      "relevance": "상담사가 아내 앞에서 말할 수 없는 이유를 물음. '어떤 상황에서도 흔들리는 내색을 하면 안 된다'는 규칙이 아내라는 가장 가까운 사람 앞에서도 감정을 꺼내지 못하게 하는 내적 기준이며, 이 규칙이 형성된 맥락(아버지의 감정 억압 요구)과 연결됨."
    }
  ]
}

